codeExamples.code:
-- Add a foreign key constraint
ALTER TABLE orders
    ADD CONSTRAINT fk_orders_customer
    FOREIGN KEY (customer_id) REFERENCES customers(customer_id);

-- Add a CHECK constraint
ALTER TABLE products
    ADD CONSTRAINT chk_price_positive CHECK (price > 0);

-- PostgreSQL: add cheaply, validate later to avoid a long lock
ALTER TABLE orders
    ADD CONSTRAINT fk_orders_customer
    FOREIGN KEY (customer_id) REFERENCES customers(customer_id) NOT VALID;
ALTER TABLE orders VALIDATE CONSTRAINT fk_orders_customer;

-- Drop a constraint
ALTER TABLE products
    DROP CONSTRAINT chk_price_positive;

-- Rename a column (MySQL 8.0 / PostgreSQL / modern SQL)
ALTER TABLE customers
    RENAME COLUMN fullname TO full_name;

-- Rename the table (PostgreSQL / MySQL 8.0)
ALTER TABLE clients
    RENAME TO customers;

-- MySQL alternative for renaming a table
RENAME TABLE clients TO customers;
